data.code:
param subscriptionId string
param budgetAmount int = 500

resource budget 'Microsoft.Consumption/budgets@2023-11-01' = {
  name: 'monthly-azure-budget'
  scope: subscriptionResourceId('Microsoft.Resources/subscriptions', subscriptionId)
  properties: {
    amount: budgetAmount
    timeGrain: 'Monthly'
    category: 'Cost'
    notifications: {
      'Actual_GreaterThan_85_Percent': {
        enabled: true
        threshold: 85
        operator: 'GreaterThan'
        contactEmails: [
          'ops@example.com'
        ]
      }
    }
  }
}
